<?php
require_once 'includes/auth.php';require_once 'includes/db.php';require_admin();$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';
 try {
  if($action==='team_add'){$s=$pdo->prepare('INSERT INTO equipes(nome,pais,sigla,descricao,logo) VALUES(?,?,?,?,?)');$s->execute([trim($_POST['nome']),trim($_POST['pais']),strtoupper(trim($_POST['sigla'])),trim($_POST['descricao']),trim($_POST['logo'])]);flash('Equipe cadastrada.');}
  elseif($action==='skater_add'){$s=$pdo->prepare('INSERT INTO patinadores(nome,pais,equipe_id,disciplina,idade,treinador,conquistas,biografia,foto) VALUES(?,?,?,?,?,?,?,?,?)');$s->execute([trim($_POST['nome']),trim($_POST['pais']),($_POST['equipe_id']?:null),$_POST['disciplina'],($_POST['idade']?:null),trim($_POST['treinador']),trim($_POST['conquistas']),trim($_POST['biografia']),trim($_POST['foto'])]);flash('Patinador cadastrado.');}
  elseif($action==='event_add'){$s=$pdo->prepare('INSERT INTO campeonatos(nome,cidade,pais,data_inicio,data_fim,categoria,status,descricao) VALUES(?,?,?,?,?,?,?,?)');$s->execute([trim($_POST['nome']),trim($_POST['cidade']),trim($_POST['pais']),$_POST['data_inicio'],$_POST['data_fim'],trim($_POST['categoria']),$_POST['status'],trim($_POST['descricao'])]);flash('Campeonato cadastrado.');}
  elseif($action==='result_save'){$id=(int)($_POST['id']??0);$pid=(int)$_POST['patinador_id'];$cid=(int)$_POST['campeonato_id'];$st=$pdo->prepare('SELECT id FROM resultados WHERE patinador_id=? AND campeonato_id=?');$st->execute([$pid,$cid]);$old=$st->fetchColumn();$sc=fn($v)=>$v===''?null:max(0,(float)$v);$tes1=$sc($_POST['sp_tes']);$pcs1=$sc($_POST['sp_pcs']);$ded1=$sc($_POST['sp_ded']??'0')??0;$tes2=$sc($_POST['fs_tes']);$pcs2=$sc($_POST['fs_pcs']);$ded2=$sc($_POST['fs_ded']??'0')??0;if($tes1===null||$pcs1===null||$tes2===null||$pcs2===null){throw new RuntimeException('Preencha TES e PCS dos dois programas.');}$total=$tes1+$pcs1-$ded1+$tes2+$pcs2-$ded2;$confirmed=isset($_POST['confirmado'])?1:0;if($old){$s=$pdo->prepare('UPDATE resultados SET programa_curto_tes=?,programa_curto_pcs=?,programa_curto_deducoes=?,programa_livre_tes=?,programa_livre_pcs=?,programa_livre_deducoes=?,total_final=?,confirmado=? WHERE id=?');$s->execute([$tes1,$pcs1,$ded1,$tes2,$pcs2,$ded2,$total,$confirmed,$old]);}else{$s=$pdo->prepare('INSERT INTO resultados(patinador_id,campeonato_id,programa_curto_tes,programa_curto_pcs,programa_curto_deducoes,programa_livre_tes,programa_livre_pcs,programa_livre_deducoes,total_final,confirmado) VALUES(?,?,?,?,?,?,?,?,?,?)');$s->execute([$pid,$cid,$tes1,$pcs1,$ded1,$tes2,$pcs2,$ded2,$total,$confirmed]);}flash($confirmed?'Resultado salvo e confirmado.':'Resultado salvo como pendente.');}
  elseif($action==='delete'){$table=$_POST['table']??'';$id=(int)$_POST['id'];$allowed=['equipes','patinadores','campeonatos'];if(in_array($table,$allowed,true)){$s=$pdo->prepare("DELETE FROM $table WHERE id=?");$s->execute([$id]);flash('Registro excluído.');}}
 }catch(Throwable $e){flash('Não foi possível concluir. Verifique os dados e vínculos.','error');}
 header('Location: admin.php');exit;
}
$teams=$pdo->query('SELECT * FROM equipes ORDER BY pais')->fetchAll();$skaters=$pdo->query('SELECT * FROM patinadores WHERE ativo=1 ORDER BY nome')->fetchAll();$events=$pdo->query('SELECT * FROM campeonatos ORDER BY data_inicio DESC')->fetchAll();$results=$pdo->query('SELECT r.*,p.nome patinador,c.nome campeonato FROM resultados r JOIN patinadores p ON p.id=r.patinador_id JOIN campeonatos c ON c.id=r.campeonato_id ORDER BY r.atualizado_em DESC')->fetchAll();$pageTitle='Administração';require 'includes/header.php'; ?>
