<section class="admin-section" id="resultado"><div class="section-heading compact"><div><span class="eyebrow">SCORING MANAGEMENT</span><h2>Lançar / editar pontuação</h2></div></div><div class="panel"><p class="muted">Pontuação por segmento: TES + PCS − deduções. Total final = programa curto + programa livre. Marque confirmar para publicar no ranking.</p><form method="post" class="admin-form"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="result_save"><label>Patinador<select name="patinador_id" required><option value="">Selecione</option><?php foreach($skaters as $s): ?><option value="<?= $s['id'] ?>"><?= e($s['nome']) ?></option><?php endforeach; ?></select></label><label>Campeonato<select name="campeonato_id" required><option value="">Selecione</option><?php foreach($events as $c): ?><option value="<?= $c['id'] ?>"><?= e($c['nome']) ?></option><?php endforeach; ?></select></label><div class="form-subtitle">PROGRAMA CURTO</div><label>TES<input type="number" name="sp_tes" min="0" max="300" step="0.01" placeholder="Ex.: 48.25"></label><label>PCS<input type="number" name="sp_pcs" min="0" max="100" step="0.01" placeholder="Ex.: 37.80"></label><label>Deduções<input type="number" name="sp_ded" min="0" max="50" step="0.01" value="0"></label><div class="form-subtitle">PROGRAMA LIVRE</div><label>TES<input type="number" name="fs_tes" min="0" max="400" step="0.01" placeholder="Ex.: 92.40"></label><label>PCS<input type="number" name="fs_pcs" min="0" max="150" step="0.01" placeholder="Ex.: 74.10"></label><label>Deduções<input type="number" name="fs_ded" min="0" max="50" step="0.01" value="0"></label><label class="check-label"><input type="checkbox" name="confirmado" value="1"> Confirmar e publicar resultado</label><button class="btn btn-dark" type="submit">Salvar pontuação ↗</button></form></div><div class="table-card"><div class="table-top"><b>Resultados cadastrados</b></div><div class="table-scroll"><table><thead><tr><th>ATLETA</th><th>CAMPEONATO</th><th>TOTAL</th><th>STATUS</th></tr></thead><tbody><?php foreach($results as $r): ?><tr><td><?= e($r['patinador']) ?></td><td><?= e($r['campeonato']) ?></td><td><?= number_format((float)$r['total_final'],2,'.','') ?></td><td><span class="status <?= $r['confirmado']?'status-finalizado':'status-agendado' ?>"><?= $r['confirmado']?'Confirmado':'Pendente' ?></span></td></tr><?php endforeach; ?></tbody></table></div></div></section>
