<section class="admin-section" id="campeonato"><div class="section-heading compact"><div><span class="eyebrow">EVENT MANAGEMENT</span><h2>Novo campeonato</h2></div></div><div class="panel"><form method="post" class="admin-form"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="event_add"><label>Nome<input name="nome" required></label><label>Categoria<input name="categoria" value="ISU Grand Prix"></label><label>Cidade<input name="cidade"></label><label>País<input name="pais"></label><label>Data inicial<input type="date" name="data_inicio" required></label><label>Data final<input type="date" name="data_fim" required></label><label>Status<select name="status"><option>Agendado</option><option>Em andamento</option><option>Finalizado</option></select></label><label class="wide">Descrição<textarea name="descricao" rows="2"></textarea></label><button class="btn btn-dark" type="submit">Adicionar campeonato ↗</button></form></div></section>
<section class="admin-section" id="equipe"><div class="section-heading compact"><div><span class="eyebrow">FEDERATION DATABASE</span><h2>Nova equipe / federação</h2></div></div><div class="panel"><form method="post" class="admin-form"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="team_add"><label>Nome da federação<input name="nome" required></label><label>País<input name="pais" required></label><label>Sigla<input name="sigla" maxlength="8" required></label><label>Bandeira / símbolo<input name="logo" placeholder="🇧🇷"></label><label class="wide">Descrição<textarea name="descricao" rows="2"></textarea></label><button class="btn btn-dark" type="submit">Cadastrar equipe ↗</button></form></div></section>
<section class="admin-section"><div class="section-heading compact"><div><span class="eyebrow">DATABASE MAINTENANCE</span><h2>Registros cadastrados</h2></div></div><div class="panel"><div class="table-scroll"><table><thead><tr><th>TIPO</th><th>NOME</th><th>AÇÃO</th></tr></thead><tbody><?php foreach($teams as $t): ?><tr><td>Equipe</td><td><?= e($t['pais']) ?> · <?= e($t['nome']) ?></td><td><form method="post" onsubmit="return confirm('Excluir esta equipe? Os atletas ficarão sem equipe.')"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="table" value="equipes"><input type="hidden" name="id" value="<?= $t['id'] ?>"><button class="btn btn-dark" type="submit">Excluir</button></form></td></tr><?php endforeach; ?><?php foreach($skaters as $s): ?><tr><td>Atleta</td><td><?= e($s['nome']) ?></td><td><form method="post" onsubmit="return confirm('Excluir este atleta e seus resultados?')"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="table" value="patinadores"><input type="hidden" name="id" value="<?= $s['id'] ?>"><button class="btn btn-dark" type="submit">Excluir</button></form></td></tr><?php endforeach; ?><?php foreach($events as $c): ?><tr><td>Campeonato</td><td><?= e($c['nome']) ?></td><td><form method="post" onsubmit="return confirm('Excluir este campeonato e seus resultados?')"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="table" value="campeonatos"><input type="hidden" name="id" value="<?= $c['id'] ?>"><button class="btn btn-dark" type="submit">Excluir</button></form></td></tr><?php endforeach; ?></tbody></table></div></div></section>
